INSERT INTO public.submission_people (submission_id,person_id,role,author_order,is_presenter,affiliation)
INSERT INTO public.person_roles (person_id, role) SELECT DISTINCT person_id, CASE WHEN is_presenter THEN 'presenter' ELSE 'author' END FROM public.submission_people WHERE author_order IS NOT NULL ON CONFLICT DO NOTHING;
INSERT INTO public.programme_days (day,label,structure_note,sort_order) VALUES ('2026-11-27','Day 1','Structure not final',1),('2026-11-28','Day 2','22 parallel rooms x 3 slots (draft)',2),('2026-11-29','Day 3','22 parallel rooms x 3 slots (draft)',3) ON CONFLICT (day) DO NOTHING;
INSERT INTO public.programme_slots (day_id,slot_no,label) SELECT d.id,n,'Slot '||n FROM public.programme_days d CROSS JOIN generate_series(1,3) n WHERE d.day IN ('2026-11-28','2026-11-29') ON CONFLICT DO NOTHING;
INSERT INTO public.programme_rooms (room_no,name) SELECT n,'Room '||n FROM generate_series(1,22) n ON CONFLICT (room_no) DO NOTHING;
